CREATE OR REPLACE FUNCTION public.amr_auditar_pacientes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  fila jsonb;
    accion_txt text;
    begin
      if TG_OP = 'DELETE' then
          fila := to_jsonb(OLD);
              accion_txt := 'borrar';
                elsif TG_OP = 'INSERT' then
                    fila := to_jsonb(NEW);
                        accion_txt := 'crear';
                          else
                              fila := to_jsonb(NEW);
                                  accion_txt := 'modificar';
                                    end if;

                                      insert into public.logs_sistema (
                                          clinica_id,
                                              usuario,
                                                  accion,
                                                      tabla,
                                                          registro_id,
                                                              detalle,
                                                                  created_at
                                                                    )
                                                                      values (
                                                                          nullif(fila->>'clinica_id','')::bigint,
                                                                              auth.uid(),
                                                                                  accion_txt,
                                                                                      'pacientes',
                                                                                          coalesce(fila->>'id',''),
                                                                                              'Paciente ' || coalesce(fila->>'nombre',''),
                                                                                                  now()
                                                                                                    );

                                                                                                      if TG_OP = 'DELETE' then
                                                                                                          return OLD;
                                                                                                            else
                                                                                                                return NEW;
                                                                                                                  end if;
                                                                                                                  end;
                                                                                                                  $function$
